function scheduleMeshPoll(){clearTimeout(state.meshPoller);state.meshPoller=null;if(!state.project)return;const waiting=state.meshTasks.filter(t=>['PENDING','IN_PROGRESS','UNKNOWN'].includes(t.status));if(!waiting.length)return;const pid=state.project.id;state.meshPoller=setTimeout(async()=>{if(!state.project||state.project.id!==pid)return;for(const task of waiting){if(!state.project||state.project.id!==pid)break;try{const r=await api('mesh-tasks/'+task.id+'/refresh',{method:'POST',json:{temp_provider:state.tempKeys[task.provider]||null}});if(r.status==='SUCCEEDED')notify('3D model ready · '+task.label);}catch(e){/* task remains queued; next refresh can retry */}}if(state.project?.id===pid)await loadMeshTasks();},18000);}
async function loadMeshTasks(){if(!state.project)return;try{const pid=state.project.id;const r=await api('projects/'+pid+'/mesh-tasks');if(state.project?.id!==pid)return;state.meshTasks=r.tasks||[];renderMeshTasks();drawMeshCards();scheduleMeshPoll();const recovery=state.meshTasks.find(t=>t.status==='SUCCEEDED'&&t.preview_status==='recoverable'&&!state.meshRecoveryAttempted.has(t.id));if(recovery){state.meshRecoveryAttempted.add(recovery.id);setTimeout(()=>{if(state.project?.id===pid)refreshMesh(recovery.id,recovery.provider,true);},800);}}catch(e){notify(e.message);}}
function currentMeshProvider(){return $('meshProvider').value||'tripo';}
function meshPrice(){const p=currentMeshProvider(),textured=$('meshTextured').checked;
 if(p==='meshy')return `${textured?30:20} Meshy credits per model`;
 if(p==='tripo')return 'Tripo credits vary by model and options · exact usage returned by provider';
 if(p==='aholo')return 'AHOLO credits depend on your account and task';
 return 'GPU cost depends on your GPU provider, compute time and deployment';}
